9422: # Opens a spool file EXCLUSIVELY (FileShare.None), retrying for $WaitMs (about 2 s; the bridge's
9423: # append 5 s - wave 28b, D6); $null when it does not exist ($Mode Open) or stays busy.
9424: function Open-TelemetrySpoolFile {
9425:     param([string]$Path, [System.IO.FileMode]$Mode = [System.IO.FileMode]::Open, [int]$WaitMs = 2000)
9426:     $watch = [System.Diagnostics.Stopwatch]::StartNew()
9427:     while ($true) {
9428:         if ($Mode -eq [System.IO.FileMode]::Open -and -not [IO.File]::Exists($Path)) { return $null }
9429:         try { return (New-Object System.IO.FileStream($Path, $Mode, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)) } catch {
9430:             if ($watch.ElapsedMilliseconds -ge $WaitMs) { return $null }
9431:             Start-Sleep -Milliseconds 50
9432:         }
9433:     }
9434: }
