9828: # POSTs with the intake's rate rule: a 429 whose Retry-After is at most 60 s - and (wave 28b, D2)
9829: # fits into $BudgetMs, what is left of the flush's deadline (0: no deadline) - is waited for and the
9830: # SAME request sent once more; a longer or missing Retry-After, or a second 429, stops there. No
9831: # other retry. Every request is bounded by $TotalMs (and by the budget).
9832: function Invoke-TelemetrySend {
9833:     param([string]$Url, [string]$Body, [int]$ConnectMs = 3000, [int]$TotalMs = 8000, [long]$BudgetMs = 0)
9834:     $watch = [System.Diagnostics.Stopwatch]::StartNew()
9835:     $one = { param([long]$Left) if ($BudgetMs -gt 0) { [int][Math]::Max(100, [Math]::Min([long]$TotalMs, $Left)) } else { $TotalMs } }
9836:     $r = Invoke-TelemetryPost -Url $Url -Body $Body -ConnectMs $ConnectMs -TotalMs (& $one ($BudgetMs - $watch.ElapsedMilliseconds))
9837:     if ($r.Status -eq 429) {
9838:         $left = $BudgetMs - $watch.ElapsedMilliseconds
9839:         if ($r.RetryAfter -ge 0 -and $r.RetryAfter -le $script:TelemetryRetryAfterMax -and ($BudgetMs -le 0 -or ([long]$r.RetryAfter * 1000 + 1000) -lt $left)) {
9840:             Start-Sleep -Seconds $r.RetryAfter
9841:             $r = Invoke-TelemetryPost -Url $Url -Body $Body -ConnectMs $ConnectMs -TotalMs (& $one ($BudgetMs - $watch.ElapsedMilliseconds))
9842:             if ($r.Status -eq 429) { $r.Why = 'HTTP 429 again after its Retry-After' }
9843:         } elseif ($r.RetryAfter -ge 0 -and $r.RetryAfter -le $script:TelemetryRetryAfterMax) {
9844:             $r.Why = "HTTP 429 (Retry-After $($r.RetryAfter) s does not fit into the flush's deadline: not retried now)"
9845:         } else {
9846:             $r.Why = "HTTP 429 (Retry-After $(if ($r.RetryAfter -ge 0) { "$($r.RetryAfter) s, more than $($script:TelemetryRetryAfterMax) s" } else { 'not given' }): not retried now)"
9847:         }
9848:     }
9849:     return $r
9850: }
